use fitig_engine::{CrawlOptions,CrawlProfile,form_auth::{Config,Credentials}};
use std::{io::{Read,Write},net::TcpListener,sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}},time::Duration};
struct Site{origin:String,requests:Arc<Mutex<Vec<(String,bool)>>>,stop:Arc<AtomicBool>,thread:Option<std::thread::JoinHandle<()>>}
impl Site{fn new()->Self{let socket=TcpListener::bind("127.0.0.1:0").unwrap();socket.set_nonblocking(true).unwrap();let origin=format!("http://{}",socket.local_addr().unwrap());let requests=Arc::new(Mutex::new(Vec::new()));let seen=requests.clone();let stop=Arc::new(AtomicBool::new(false));let done=stop.clone();let thread=std::thread::spawn(move||while !done.load(Ordering::SeqCst){match socket.accept(){Ok((mut stream,_))=>{stream.set_nonblocking(false).unwrap();stream.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut head=Vec::new();let mut byte=[0];while head.len()<32768&&!head.ends_with(b"\r\n\r\n"){if stream.read(&mut byte).unwrap_or(0)!=1{break}head.push(byte[0])}let head=String::from_utf8_lossy(&head);let line=head.lines().next().unwrap_or("");let path=line.split_whitespace().nth(1).unwrap_or("").to_string();let authorized=head.lines().any(|line|line.to_ascii_lowercase().starts_with("cookie:")&&line.contains("session=owned-cookie"));seen.lock().unwrap().push((path.clone(),authorized));let length=head.lines().find_map(|line|line.split_once(':').filter(|(key,_)|key.eq_ignore_ascii_case("content-length")).and_then(|(_,v)|v.trim().parse::<usize>().ok())).unwrap_or(0);let mut body=vec![0;length.min(16384)];let _=stream.read_exact(&mut body);
 let(code,extra,text)=if line.starts_with("POST "){let values:url::form_urlencoded::Parse<'_>=url::form_urlencoded::parse(&body);let fields=values.into_owned().collect::<std::collections::BTreeMap<_,_>>();if fields.get("user").map(String::as_str)==Some("owned-user")&&fields.get("pass").map(String::as_str)==Some("owned-secret")&&fields.get("csrf").map(String::as_str)==Some("token&one"){(302,"Set-Cookie: session=owned-cookie; HttpOnly; Path=/\r\nLocation: /must-not-follow\r\n","redirect")}else{(403,"","wrong")}}else if path=="/login"{(200,"","<form><input name='csrf' value='token&amp;one'></form>")}else if path=="/verify"{if authorized{(200,"","<h1>AUTHENTICATED FIXTURE</h1>")}else{(200,"","<h1>Login again</h1>")}}else if path=="/robots.txt"{if authorized{(200,"","User-agent: *\nAllow: /")}else{(403,"","denied")}}else if authorized{(200,"","<title>Private</title>")}else{(401,"","not authenticated")};let _=write!(stream,"HTTP/1.1 {code} Test\r\nContent-Length: {}\r\nContent-Type: text/html; charset=utf-8\r\nConnection: close\r\n{extra}\r\n{text}",text.len());},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>std::thread::sleep(Duration::from_millis(3)),Err(_)=>break}});Self{origin,requests,stop,thread:Some(thread)}}}
impl Drop for Site{fn drop(&mut self){self.stop.store(true,Ordering::SeqCst);if let Some(thread)=self.thread.take(){let _=thread.join();}}}
fn profile(site:&Site)->CrawlProfile{CrawlProfile{form_auth:Some(Config{login_url:format!("{}/login",site.origin),verify_url:format!("{}/verify",site.origin),success_text:"AUTHENTICATED FIXTURE".into(),username_field:"user".into(),password_field:"pass".into(),csrf_field:"csrf".into()}),cookies_enabled:true,proxy_mode:"direct".into(),..Default::default()}}
fn credentials()->Credentials{Credentials{username:"owned-user".into(),password:"owned-secret".into()}}
fn file()->std::path::PathBuf{std::env::temp_dir().join(format!("fitig-form-{}-{}.sqlite",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()))}
#[test]fn form_csrf_verification_and_authenticated_crawl_preserve_credentials(){let site=Site::new();let db=file();let p=profile(&site);let pages=fitig_engine::crawl_with_sessions_and_renderer(CrawlOptions{url:format!("{}/",site.origin),db:db.to_string_lossy().into(),limit:0,delay_ms:0,resume:false},None,p.clone(),None,None,Some(credentials()),fitig_engine::render::render,|_|{}).unwrap();assert_eq!(pages.len(),1);assert_eq!(pages[0].title,"Private");let requests=site.requests.lock().unwrap();assert_eq!(requests.iter().filter(|(url,_)|url=="/login").count(),2);assert!(!requests.iter().any(|(url,_)|url=="/must-not-follow"));assert!(requests.iter().filter(|(url,_)|url=="/robots.txt"||url=="/").all(|(_,auth)|*auth));drop(requests);let bytes=std::fs::read(&db).unwrap();let text=String::from_utf8_lossy(&bytes);for secret in ["owned-user","owned-secret","owned-cookie","token&one"]{assert!(!text.contains(secret));assert!(!serde_json::to_string(&pages).unwrap().contains(secret));}assert_eq!(fitig_engine::project_profile(db.to_str().unwrap()).unwrap(),p);std::fs::remove_file(db).unwrap();}
#[test]fn failed_verification_and_missing_credentials_create_no_project(){let site=Site::new();let mut p=profile(&site);p.form_auth.as_mut().unwrap().success_text="not present".into();for creds in [None,Some(credentials())]{let db=file();let result=fitig_engine::crawl_with_sessions_and_renderer(CrawlOptions{url:format!("{}/",site.origin),db:db.to_string_lossy().into(),limit:0,delay_ms:0,resume:false},None,p.clone(),None,None,creds,fitig_engine::render::render,|_|{});assert!(result.is_err());assert!(!db.exists());}assert!(!site.requests.lock().unwrap().iter().any(|(url,_)|url=="/"));}
#[test]fn scoped_cookie_jar_never_releases_cookies_to_other_ports_or_protocols(){use reqwest::{cookie::CookieStore,header::HeaderValue};let jar=fitig_engine::http_cookies::Jar::new_scoped("https://e.test").unwrap();let header=HeaderValue::from_static("session=owned; Domain=e.test; Path=/; Secure");let url="https://e.test/".parse().unwrap();jar.set_cookies(&mut std::iter::once(&header),&url);assert!(jar.cookies(&url).is_some());for url in ["https://e.test:444/","http://e.test/","https://child.e.test/"]{assert!(jar.cookies(&url.parse().unwrap()).is_none())}}
#[test]fn missing_csrf_stops_before_submission_and_wrong_password_errors_are_sanitized(){let site=Site::new();let mut p=profile(&site);p.form_auth.as_mut().unwrap().csrf_field="absent".into();assert!(fitig_engine::form_auth::authenticate(&p,&credentials()).is_err());assert_eq!(site.requests.lock().unwrap().len(),1);let p=profile(&site);let error=fitig_engine::form_auth::authenticate(&p,&Credentials{username:"owned-user".into(),password:"wrong-sensitive-value".into()}).unwrap_err().to_string();assert!(!error.contains("wrong-sensitive-value"));assert!(!site.requests.lock().unwrap().iter().any(|(url,_)|url=="/verify"));}
#[test]fn encrypted_checkpoint_retains_exact_origin_lock(){use reqwest::{cookie::CookieStore,header::HeaderValue};let db=file();let jar=fitig_engine::http_cookies::Jar::new_scoped("http://127.0.0.1:12345").unwrap();let header=HeaderValue::from_static("session=protected-owned-value; Path=/");let origin="http://127.0.0.1:12345/".parse().unwrap();jar.set_cookies(&mut std::iter::once(&header),&origin);let c=rusqlite::Connection::open(&db).unwrap();c.execute_batch("CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL); CREATE TABLE pages(url TEXT PRIMARY KEY,json TEXT NOT NULL); CREATE TABLE frontier(url TEXT PRIMARY KEY,depth INTEGER); INSERT INTO metadata VALUES('seed','http://127.0.0.1:12345/')").unwrap();jar.checkpoint(&c).unwrap();let envelope:String=c.query_row("SELECT value FROM metadata WHERE key='http-cookie-state'",[],|row|row.get(0)).unwrap();assert!(envelope.contains("windows-dpapi-origin-v2"));drop(c);let restored=fitig_engine::http_cookies::Jar::restore(db.to_str().unwrap()).unwrap().unwrap();assert!(restored.cookies(&origin).is_some());assert!(restored.cookies(&"http://127.0.0.1:12346/".parse().unwrap()).is_none());assert!(!String::from_utf8_lossy(&std::fs::read(&db).unwrap()).contains("protected-owned-value"));std::fs::remove_file(db).unwrap();}
